def simulate(I, grav_left=True):
    H,W=len(I),len(I[0])
    P=[(r,c,I[r][c]) for r in range(H) for c in range(W) if I[r][c] not in (7,2)]
    out=[row[:] for row in I]
    def blocked(r,c):
        return not(0<=r<H and 0<=c<W) or out[r][c]==8
    while True:
        moved=False
        P.sort(key=lambda p:-p[0])
        for i,(r,c,v) in enumerate(P):
            if grav_left:
                nr,nc=r,c-1
                if not blocked(nr,nc) and not blocked(nr,nc+1):  # diag support needed? try without first
                    out[r][c]=7; out[nr][nc]=v; P[i]=(nr,nc,v); moved=True
            else:
                nr,nc=r,c+1
                if not blocked(nr,nc) and not blocked(nr,nc-1):
                    out[r][c]=7; out[nr][nc]=v; P[i]=(nr,nc,v); moved=True
        if not moved: break
    return out

