def solve(I):
    H,W=len(I),len(I[0])
    cells=[(r,c,I[r][c]) for r in range(H) for c in range(W) if I[r][c]!=I[0][0]]
    # marker = straight line of a repeated color; object = rest
    lines=[]
    for v,r,c in cells:
        pass
    # find longest straight run
    best=None
    for r in range(H):
        runs=[]
        c=0
        while c<W:
            if I[r][c]==I[0][0]: c+=1; continue
            c0=c
            while c<W and I[r][c]!=I[0][0]: c+=1
            if c-c0>len(best[1]) if best else True: best=(r,c0,c,'h')
        c=0
    for c in range(W):
        r=0
        while r<H:
            if I[r][c]==I[0][0]: r+=1; continue
            r0=r
            while r<H and I[r][c]!=I[0][0]: r+=1
            if r-r0>len(best[1]) if best else True: best=(c,r0,r,'v')
    mc,best=best
    axis=best[3]
    marker_cells={(mc,b) for b in range(H) if axis=='v'} | {(b,mc) for b in range(W) if axis=='h'}
    o=set((r,c) for r,c,v in cells if (r,c) not in marker_cells)
    def contact():
        return any(abs(a[0]-b[0])<=1 and abs(a[1]-b[1])<=1 for a in o for b in marker_cells)
    if contact(): O=[row[:] for row in I]
    else:
        D=(-1,1) if axis=='v' else (1,-1)  # toward marker
        while True:
            o={((r+D[0],c+D[1]),I[r][c]) for r,c,v in o}
            if contact(): break
            if not (0<=r:=min(a[0] for a in o) and all(0<=c< W for r,c in o)):
                break
        O=[row[:] for row in I]
        for (r,c),v in o: O[r][c]=v
        # stripe: adjacent to far side of object along axis, color 8
        far=(max(a[0] for a in o) if axis=='h' else max(a[1] for a in o))
        nr=(far+1 if axis=='h' else far+1)
        s=[]
        for r in range(H): s.append((r,nr)) if False else None
        S=[(r,nr) for r in range(H)] if axis=='v' else [(nr,c) for c in range(W)]
        for p in S: O[p[0]][p[1]]=8
    return O

