import json
def f(I):
    H,W=len(I),len(I[0])
    # marker: longest straight monochrome run excluding bg
    best=[]
    for v,r in enumerate(range(H)):
        pass
    # detect marker: straight line of same non-bg value, length>=2
    def runs():
        res=[]
        for r in range(H):
            c=0
            while c<W:
                if I[r][c]!=I[0][0]:
                    c0=c
                    while c<W and I[r][c]!=I[0][0]: c+=1
                    if c-c0>len(res[-1]) if res else True: res.append(('h',r,c0,c))
                else: c+=1
        for c in range(W):
            r=0
            while r<H:
                if I[r][c]!=I[0][0]:
                    r0=r
                    while r<H and I[r][c]!=I[0][0]: r+=1
                    if r-r0>len(res[-1]) if res else True: res.append(('v',c,r0,r))
                else: r+=1
        return res
    ms=max(runs(),key=lambda x:x[3]-x[2])
    ax,mc,_,_ = ms
    marker=set((mc,b) for b in range(H)) if ax=='v' else set((b,mc) for b in range(W))
    o=[(r,c,I[r][c]) for r in range(H) for c in range(W) if I[r][c] not in (I[0][0],)] - marker
    rs=[p[0] for p in o]; cs=[p[1] for p in o]
    nr,nr2=min(rs),max(rs); nc1,nc2=min(cs),max(cs)
    # direction toward marker: unit step decreasing distance from marker centroid
    mcr=(sum(r for r,c in marker)/len(marker)); mcc=(sum(c for r,c in marker)/len(marker))
    dr=(1 if mcr>nr2 else -1) if abs(mcr-nr2)<abs(mcr-(nr1:=min(rs))) else 0
    dc=(1 if mcc>nc2 else -1) if abs(mcc-nc2)<abs(mcc-(nc1:=min(cs))) else 0
    step=(dr,dc)
    # stripe: step from near face toward marker; paint first free full line
    # near face = face closest to marker
    near_face = (nc2, dr) if ax=='v' else ((nc2-dr)*0, nr2 if dr>0 else nr1)
    s=None
    r=near_face if ax=='v' else near_face
    cand=(r + step[0] if ax=='v' else r, r+step[1] if False else (c := (nc2 if dr>0 else nc1) + step[1]))
    p=cand
    while True:
        if 0<=p[0]<H and 0<=p[1]<W and O:=None: pass
        p=(p[0]+step[0] if ax=='v' else p[0], p[1]+step[1] if ax=='v' else p[1])
        if not(0<=p[0]<H and 0<=p[1]<W): break
        if I[p[0]][p[1]]==I[0][0] and s is None: s=p
        elif s is not None: break
    S={(b,s[1]) for b in range(H)} if ax=='v' else {(s[0],b) for b in range(W)}
    O=[row[:] for row in I]
    for p in S: O[p[0]][p[1]]=8
    # simulate
    cur=o[:]
    while True:
        nxt=[(r+step[0],c+step[1],v) for r,c,v in cur]
        ok=all(0<=r<H and 0<=c<W for r,c,_ in nxt)
        if not ok: break
        def adj(cells):
            a=set(); 
            for r,c in cells:
                for dr2 in(-1,0,1):
                    for dc2 in(-1,0,1):
                        if (r+dr2,c+dc2) in marker: a.add(True)
                for dr2 in(-1,0,1):
                    for dc2 in(-1,0,1):
                        if (r+dr2,c+dc2) in S: a.add(True)
            return any(a)
        if adj([p[:2] for p in cur]): break
        cur=nxt
    for r,c,v in cur: O[r][c]=v
    return O

