d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

def f(I):
    H,W=len(I),len(I[0])
    cnt=Counter(x for row in I for x in row); bg=cnt.most_common(1)[0][0]
    mothe='col'; mc=None
    for c in range(W):
        cs={I[r][c] for r in range(H)}
        if len(cs)==1 and next(iter(cs))!=bg: mc=c; break
    else:
        mothe='row'; mc=None
        for r in range(H):
            if len(set(I[r]))==1 and I[r][0]!=bg: mc=r; break
    marker={(mc,b) for b in range(H)} if mothe=='col' else {(b,mc) for b in range(W)}
    comps=[]; seen=set()
    for r in range(H):
        for c in range(W):
            v=I[r][c]
            if v!=bg and (r,c) not in marker and (r,c) not in seen:
                stack=[(r,c)]; comp=[]
                while stack:
                    a,b=stack.pop()
                    if (a,b) in seen or I[a][b]!=v: continue
                    seen.add((a,b)); comp.append((a,b,v))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and (x,y) not in seen and I[x][y]==v: stack.append((x,y))
                comps.append(comp)
    def dcomp(comp):
        return min(abs(p[mothe.replace('col','0')] if mothe=='col' else p[mothe.replace('row','1')] if False 
                  else (p[0] if mothe=='col' else p[1])-mc) for p in comp)
    best=min(comps,key=dcomp)
    cur=[list(p) for p in best]
    if mothe=='col':
        lo=min(c for _,_ in cur); hi=max(c for _,_ in cur)
        step=(1 if lo<mc else (-1 if hi>mc else 0))
    else:
        lo=min(r for _,_ in cur); hi=max(r for _,_ in cur)
        step=(1 if lo<mc else (-1 if hi>mc else 0))
    while True:
        n=[(r+step,c) for r,c in cur]
        ok=all(0<=r<H and 0<=c<W for r,c in n)
        nxt=set(n)
        if not ok or nxt & marker: break
        cur=n
    out=[row[:] for row in I]
    newpos={(a,b) for a,b in cur}
    for r,c,v in cur: out[r][c]=v
    for r,c,v in best:
        if (r,c) not in newpos: out[r][c]=bg
    if mothe=='col':
        lo=min(c for _,_ in cur); hi=max(c for _,_ in cur)
        sr = lo-1 if lo<mc else hi+1
        S={(sr,r) for r in range(H)}
    else:
        lo=min(r for _,_ in cur); hi=max(r for _,_ in cur)
        sr = lo-1 if lo<mc else hi+1
        S={(sr,c) for c in range(W)}
    for r,c in S:
        if out[r][c]==bg: out[r][c]=8
    return out

